package owl.nh;

/** Regression scenarios for prayer ownership, healing, confirmed sips and multi-step entry. */
public final class OlmPriorityTests {
 static void check(boolean ok,String message){CoreTests.check(ok,"Olm priority: "+message);}
 public static void main(String[] args){
  OlmSpecActivation activation=new OlmSpecActivation();check(activation.mayRequest(100),"initial special activation permitted");activation.requested(100);for(int i=0;i<50;i++)check(!activation.mayRequest(100),"same-tick polls cannot toggle special back off");check(!activation.mayRequest(101)&&!activation.mayRequest(102)&&activation.mayRequest(103),"unacknowledged special has a bounded three-tick retry window");activation.observe(true);activation.observe(true);check(activation.diagnostics().get("observedActivations")==1,"activation is confirmed once rather than inferred from a click");activation.reset();check(activation.mayRequest(0),"new raid clears activation retry state");
  OlmAidRecovery recovery=new OlmAidRecovery();int[] base={99,99,99,99,99},full={120,120,120,120,120},low={97,96,95,94,93};recovery.observe(true,base,full);recovery.observe(true,base,low);check(!recovery.needed(),"low stats without confirmed aid do not trigger this recovery rule");recovery.consumed("aid");recovery.observe(true,base,low);check(recovery.needed(),"confirmed aid plus active overload and stats below 100 needs revitalisation without a time check");recovery.consumed("revitalisation");recovery.observe(true,base,new int[]{99,99,99,99,99});check(!recovery.needed(),"one confirmed revitalisation cannot loop while stats remain below 100");recovery.consumed("aid");recovery.observe(true,base,new int[]{100,100,100,100,100});check(!recovery.needed(),"exactly 100 does not trigger a sip");recovery.observe(true,base,low);check(recovery.needed(),"later observed depletion after aid is detected");recovery.observe(true,base,full);check(!recovery.needed(),"observed natural overload refresh cancels unnecessary recovery");recovery.consumed("aid");recovery.observe(false,base,low);check(!recovery.needed(),"expired overload does not activate the post-aid rule");recovery.reset();recovery.consumed("aid");recovery.observe(true,new int[]{50,50,50,50,50},new int[]{60,60,60,60,60});check(!recovery.needed(),"naturally sub-100 boosted skills do not waste restores");
  OlmStrategy brewStrategy=new OlmStrategy();for(int i=0;i<7;i++)brewStrategy.drinkConfirmed();OlmStrategy.View brewed=OlmStrategyTests.ready();brewed.entered=true;brewed.phase=OlmStrategy.Phase.HEAD;brewed.headAlive=true;brewed.hp=99;brewed.prayerPoints=99;brewed.aidStatsDepleted=true;check(brewStrategy.choose(brewed).value.equals("revitalisation"),"in-combat depleted stats request a revitalisation sip");brewed.hp=50;check(brewStrategy.choose(brewed).value.equals("aid"),"urgent healing precedes stat recovery");brewed.hp=99;brewed.prayerRequired=true;check(brewStrategy.choose(brewed).kind==OlmStrategy.Kind.WAIT,"protection priority precedes stat recovery");brewed.prayerRequired=false;brewed.potionPending=true;check(brewStrategy.choose(brewed).kind!=OlmStrategy.Kind.DRINK,"stat recovery respects confirmed potion cooldowns");brewed.potionPending=false;brewed.unavailableSupplies.add("revitalisation");check(brewStrategy.choose(brewed).kind!=OlmStrategy.Kind.DRINK,"missing restores do not stall combat");

  OlmPotionFlow p=new OlmPotionFlow();p.reset(100);p.requested("overload",8,100,true);
  check(p.observe(8,101,3)==OlmPotionFlow.Result.NONE&&!p.ready(101),"unconsumed click cannot advance or click the next potion");
  check(p.observe(7,102,3)==OlmPotionFlow.Result.CONFIRMED&&p.preparationCredit(),"exact one-dose consumption confirms preparation");
  check(!p.ready(104)&&p.ready(105),"cooldown begins at observed consumption rather than an earlier click");
  p.requested("enhance",4,105,true);check(p.observe(4,109,3)==OlmPotionFlow.Result.NONE,"no repeated sip while waiting for response");check(p.observe(4,110,3)==OlmPotionFlow.Result.TIMED_OUT&&!p.preparationCredit(),"failed sip does not advance preparation");check(!p.ready(110)&&p.ready(111),"unconfirmed click uses bounded retry instead of spamming");
  p.requested("aid",12,111,false);check(p.observe(9,112,3)==OlmPotionFlow.Result.NONE,"dropping a vial is not a confirmed sip");
  OlmPotionFlow rhythm=new OlmPotionFlow();rhythm.reset(237);int doses=20;for(int request:new int[]{237,241,245,249}){check(rhythm.ready(request),"next sip ready after three ticks from observed consumption");rhythm.requested("aid",doses,request,true);doses--;check(rhythm.observe(doses,request+1,3)==OlmPotionFlow.Result.CONFIRMED,"one consumed dose at the next observed tick");check(!rhythm.ready(request+3),"changed request phase cannot cause a two-tick consumption gap");}
  OlmStrategy strategy=new OlmStrategy();OlmStrategy.View s=OlmStrategyTests.ready();s.entered=true;s.hp=80;s.hpPercent=99;s.magicAlive=true;
  s.prayerRequired=true;check(strategy.choose(s).kind==OlmStrategy.Kind.WAIT,"prayer dominates healing and preparation");s.prayerRequired=false;OlmStrategy.Choice heal=strategy.choose(s);check(heal.value.equals("aid")&&!heal.preparationCredit,"absolute HP at eighty overrides offence without skipping overload");
  s.hp=81;check(strategy.choose(s).value.equals("overload"),"above eighty HP clears healing threshold");
  for(int i=0;i<7;i++)strategy.drinkConfirmed();s.hp=50;check(strategy.choose(s).value.equals("aid"),"completed preparation still heals before DPS");s.hp=81;s.phase=OlmStrategy.Phase.REGULAR;check(strategy.choose(s).value.equals("magic"),"DPS permitted only after health threshold and prayer readiness");
  strategy.reset();strategy.overloadAlreadyActive();check(strategy.choose(s).value.equals("enhance"),"confirmed active overload avoids another fifty-HP dose");
  OlmEntryFlow e=new OlmEntryFlow();check(e.next(1,true,false,false,false)==OlmEntryFlow.Action.CLICK_GATE,"first gate click");e.sentGate(1);
  check(e.next(2,true,true,true,false)==OlmEntryFlow.Action.CLICK_BEGIN,"visible Begin the raid selected after first click");e.sentBegin(2);check(!e.insideEvidence(true,false),"visible actors after Begin cannot skip the second gate click");check(e.next(3,true,true,true,false)==OlmEntryFlow.Action.WAIT,"begin is not spammed while dismissal is pending");
  check(e.next(4,true,false,false,false)==OlmEntryFlow.Action.WAIT,"transient dialogue gap never triggers another gate");check(e.next(39,true,false,false,false)==OlmEntryFlow.Action.CLICK_GATE,"second gate click after confirmation disappears");e.sentGate(39);check(!e.insideEvidence(true,false)&&e.insideEvidence(false,true),"second gate requires an observed crossing instead of room visibility alone");check(e.stage()==OlmEntryFlow.Stage.WAIT_INSIDE&&e.next(40,true,false,false,false)==OlmEntryFlow.Action.WAIT,"second click alone does not prove entry");
  e.next(41,true,false,false,true);check(e.stage()==OlmEntryFlow.Stage.INSIDE,"observed crossing completes entry");
  check(OlmEntryFlow.beginText("<col=ffff00>Begin the raid.</col>")&&!OlmEntryFlow.beginText("Leave the raid")&&!OlmEntryFlow.beginText("Begin a different raid"),"exact requested option only");
  e.reset();e.sentGate(10);check(e.next(20,false,true,true,false)==OlmEntryFlow.Action.CLICK_BEGIN,"dialogue works even when gate object changes/disappears");
  e.reset();e.sentGate(10);check(e.next(109,true,false,false,false)==OlmEntryFlow.Action.WAIT,"ignored first gate has a bounded observation wait");check(e.next(110,true,false,false,false)==OlmEntryFlow.Action.CLICK_GATE,"ignored first gate is retried without assuming entry");e.sentGate(110);e.sentBegin(111);check(e.next(145,true,true,true,false)==OlmEntryFlow.Action.WAIT,"ignored chatbox click is not spammed");check(e.next(146,true,true,true,false)==OlmEntryFlow.Action.CLICK_BEGIN&&e.keyboardConfirmation(),"ignored chatbox click enables numbered option fallback");e.sentBegin(146);check(e.next(148,true,false,false,false)==OlmEntryFlow.Action.WAIT,"dialogue must remain clear before entry retry");check(e.next(183,true,false,false,false)==OlmEntryFlow.Action.CLICK_GATE,"observed confirmation dismissal requires second gate interaction");e.sentGate(183);check(e.next(243,true,false,false,false)==OlmEntryFlow.Action.CLICK_GATE,"ignored second gate is retried while entry remains unconfirmed");
  check(OlmEntryFlow.beginOption(java.util.Arrays.asList("Begin the raid","Leave"))==1&&OlmEntryFlow.beginOption(java.util.Arrays.asList("Leave","2: Begin the raid."))==2,"confirm key follows observed option text, including reordered options");check(OlmEntryFlow.beginOption(java.util.Arrays.asList("Leave","Cancel"))==-1&&OlmEntryFlow.beginOption(java.util.Arrays.asList("Begin raid","Begin raid"))==-1,"unrelated and ambiguous dialogue never gets a guessed number key");
  check(OlmEntryPreparation.need(false,true,true,true)==OlmEntryPreparation.Need.FINISH_POTTING,"entry never precedes confirmed potting");check(OlmEntryPreparation.need(true,false,true,true)==OlmEntryPreparation.Need.MAGIC_GEAR,"entry requires observed mage equipment");check(OlmEntryPreparation.need(true,true,false,true)==OlmEntryPreparation.Need.MAGIC_PROTECTION,"entry requires observed magic protection");check(OlmEntryPreparation.need(true,true,true,false)==OlmEntryPreparation.Need.MAGIC_BOOST,"entry requires observed magic offensive prayer");check(OlmEntryPreparation.need(true,true,true,true)==OlmEntryPreparation.Need.ENTER,"only confirmed full entry setup admits gate actions");
  System.out.println("Olm priority checks passed: prayers before supplies/DPS, absolute above eighty HP, acknowledged three-tick potion cooldown, failed sips, and gate/begin/gate/observed-entry protocol. Synthetic only.");
 }
}
